// Gerado automaticamente por transpilador_pt/bundle_web.py — não editar manualmente
window.TRANSPILADOR_PT_SOURCES = {
  "__init__.py": "from .transpiler import transpila, transpila_canonico, ErroDeTraducao\nfrom .executor import executa_codigo, executa_arquivo\nfrom .transicao import renderiza_lado_a_lado\n\n__version__ = \"0.1.0\"\n\n__all__ = [\n    \"__version__\",\n    \"transpila\",\n    \"transpila_canonico\",\n    \"ErroDeTraducao\",\n    \"executa_codigo\",\n    \"executa_arquivo\",\n    \"renderiza_lado_a_lado\",\n]\n\n",
  "dicionario.py": "\"\"\"\nDicionário de tradução PT -> Python.\n\nUm único mapa cobre tanto palavras reservadas (se, para, enquanto...)\nquanto builtins comuns (mostre, leia, tamanho...), porque para o\ntokenizer do Python ambos são apenas tokens NAME -- não existe\ndistinção sintática entre \"palavra reservada\" e \"nome de função\" no\nnível de token, só no nível de parser/AST.\n\nIMPORTANTE (limitação conhecida, discutida na conversa): algumas\nchaves aqui são palavras muito comuns no português cotidiano\n(\"em\", \"e\", \"ou\", \"com\", \"como\"). Isso significa que essas palavras\nficam indisponíveis como nomes de variável, exatamente como \"in\",\n\"and\", \"or\" também são reservadas em inglês. É um trade-off\ninerente a essa abordagem, não um bug.\n\"\"\"\n\nimport builtins\n\n# --- Palavras-chave estruturais -------------------------------------------\nPALAVRAS_CHAVE = {\n    \"se\": \"if\",\n    \"senao\": \"else\",          # sem acento, teclado-friendly\n    \"senão\": \"else\",\n    \"senaose\": \"elif\",\n    \"senãose\": \"elif\",\n    \"ouse\": \"elif\",           # legado / retrocompatibilidade\n    \"para\": \"for\",\n    \"enquanto\": \"while\",\n    \"funcao\": \"def\",\n    \"função\": \"def\",\n    \"retorne\": \"return\",\n    \"classe\": \"class\",\n    \"importe\": \"import\",\n    \"de\": \"from\",\n    \"como\": \"as\",\n    \"com\": \"with\",\n    \"tente\": \"try\",\n    \"exceto\": \"except\",\n    \"finalmente\": \"finally\",\n    \"levante\": \"raise\",\n    \"quebre\": \"break\",\n    \"continue\": \"continue\",\n    \"passe\": \"pass\",\n    \"em\": \"in\",\n    \"nao\": \"not\",\n    \"não\": \"not\",\n    \"e\": \"and\",\n    \"ou\": \"or\",\n    \"lambda\": \"lambda\",\n    \"global\": \"global\",\n    \"assincrono\": \"async\",\n    \"aguarde\": \"await\",\n    \"produza\": \"yield\",\n    \"del\": \"del\",\n    \"assert\": \"assert\",\n    \"verdadeiro\": \"True\",\n    \"falso\": \"False\",\n    \"nulo\": \"None\",\n}\n\n# MAPA utilizado pelo transpilador léxico para alterar tokens sintáticos\nMAPA = PALAVRAS_CHAVE\n\n# --- Builtins curados (fonte única) -----------------------------------------\n# Mapeia o nome pedagógico em português para o nome canônico do builtin Python.\n# Esta é a única fonte de verdade: tanto a injeção em runtime (ADR-001) quanto a\n# exportação canônica (ADR-003) são derivadas daqui, evitando dessincronização.\nBUILTINS_CANONICOS = {\n    \"mostre\": \"print\",\n    \"mostra\": \"print\",\n    \"leia\": \"input\",\n    \"tamanho\": \"len\",\n    \"intervalo\": \"range\",\n    \"tipo\": \"type\",\n    \"texto\": \"str\",\n    \"inteiro\": \"int\",\n    \"decimal\": \"float\",\n    \"booleano\": \"bool\",\n    \"lista\": \"list\",\n    \"dicionario\": \"dict\",\n    \"dicionário\": \"dict\",\n    \"conjunto\": \"set\",\n    \"tupla\": \"tuple\",\n    \"ordene\": \"sorted\",\n    \"inverta\": \"reversed\",\n    \"some\": \"sum\",\n    \"maximo\": \"max\",\n    \"máximo\": \"max\",\n    \"minimo\": \"min\",\n    \"mínimo\": \"min\",\n    \"absoluto\": \"abs\",\n    \"arredonde\": \"round\",\n    \"enumere\": \"enumerate\",\n    \"zip\": \"zip\",\n    \"mapeie\": \"map\",\n    \"filtre\": \"filter\",\n}\n\n# Builtins injetados em runtime (ADR-001), derivados da fonte única acima\n# resolvendo cada nome canônico para o objeto builtin correspondente.\nBUILTINS_PT = {\n    nome_pt: getattr(builtins, nome_canonico)\n    for nome_pt, nome_canonico in BUILTINS_CANONICOS.items()\n}\n\n# Singletons cujo destaque visual é distinto de palavras-chave comuns\n# (booleanos e nulo, em PT e em Python canônico).\nSINGLETONS_DESTAQUE = (\"verdadeiro\", \"falso\", \"nulo\", \"True\", \"False\", \"None\")\n\n\ndef conjuntos_de_destaque() -> dict[str, list[str]]:\n    \"\"\"Deriva os conjuntos de realce de sintaxe usados pelo playground web.\n\n    Fonte única para a coloração do editor: em vez de manter listas paralelas\n    à mão em ``app.js``, os grupos são gerados a partir dos mesmos dicionários\n    que governam a tradução (``PALAVRAS_CHAVE`` e ``BUILTINS_CANONICOS``),\n    cobrindo tanto os nomes em português quanto os equivalentes canônicos.\n    \"\"\"\n    singletons = set(SINGLETONS_DESTAQUE)\n\n    palavras_chave = set()\n    for nome_pt, nome_py in PALAVRAS_CHAVE.items():\n        if nome_pt in singletons or nome_py in singletons:\n            continue\n        palavras_chave.add(nome_pt)\n        palavras_chave.add(nome_py)\n\n    builtins_destaque = set()\n    for nome_pt, nome_py in BUILTINS_CANONICOS.items():\n        builtins_destaque.add(nome_pt)\n        builtins_destaque.add(nome_py)\n\n    return {\n        \"palavrasChave\": sorted(palavras_chave),\n        \"builtins\": sorted(builtins_destaque),\n        \"booleanos\": sorted(singletons),\n    }\n\n",
  "escopo_canonico.py": "\"\"\"Análise de escopo léxico para a exportação canônica (ADR-003).\n\nExtraído de ``transpiler.py`` para isolar uma responsabilidade coesa: mapear,\nvia ``ast`` e ``symtable``, quais nomes de cada escopo devem manter a grafia em\nportuguês (parâmetros, locais, nomes que sombreiam builtins) e localizar, no\nfluxo de tokens original em PT, as declarações de parâmetros. O núcleo léxico\ndo transpilador consome apenas ``ScopeInfo`` e ``build_scope_context``.\n\nEste módulo é puramente derivado da stdlib e não depende do dicionário de\ntradução nem do núcleo léxico, mantendo a dependência em sentido único\n(transpiler -> escopo_canonico).\n\"\"\"\n\nfrom __future__ import annotations\n\nimport ast\nimport difflib\nimport symtable\nimport token\nimport tokenize\nfrom dataclasses import dataclass\n\n\n@dataclass(frozen=True)\nclass ScopeInfo:\n    \"\"\"Binding information for the body of one Python lexical scope.\"\"\"\n\n    start_line: int\n    start_column: int\n    end_line: int\n    protected_names: frozenset[str]\n\n\ndef _scope_key(node: ast.AST) -> tuple[str, str, int] | None:\n    \"\"\"Return the symbol-table identity for a scope-bearing AST node.\"\"\"\n    if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):\n        return \"function\", node.name, node.lineno\n    if isinstance(node, ast.ClassDef):\n        return \"class\", node.name, node.lineno\n    if isinstance(node, ast.Lambda):\n        return \"function\", \"lambda\", node.lineno\n    if isinstance(node, ast.ListComp):\n        return \"function\", \"listcomp\", node.lineno\n    if isinstance(node, ast.SetComp):\n        return \"function\", \"setcomp\", node.lineno\n    if isinstance(node, ast.DictComp):\n        return \"function\", \"dictcomp\", node.lineno\n    if isinstance(node, ast.GeneratorExp):\n        return \"function\", \"genexpr\", node.lineno\n    return None\n\n\ndef _scope_span(node: ast.AST) -> tuple[ast.AST, int, int] | None:\n    \"\"\"Return the AST start node and line range covered by a scope.\"\"\"\n    if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):\n        if not node.body:\n            return None\n        start_node = node.body[0]\n        end_node = node.body[-1]\n    elif isinstance(node, ast.Lambda):\n        start_node = end_node = node.body\n    elif isinstance(node, (ast.ListComp, ast.SetComp, ast.DictComp, ast.GeneratorExp)):\n        start_node = node\n        end_node = node\n    else:\n        return None\n    return (\n        start_node,\n        start_node.lineno,\n        getattr(end_node, \"end_lineno\", end_node.lineno),\n    )\n\n\ndef _map_canonical_column_to_source(\n    canonical_line: str,\n    source_line: str,\n    canonical_column: int,\n) -> int:\n    \"\"\"Map an AST byte column through spacing and keyword substitutions.\"\"\"\n    try:\n        canonical_char_column = len(\n            canonical_line.encode(\"utf-8\")[:canonical_column].decode(\"utf-8\")\n        )\n    except UnicodeDecodeError:\n        canonical_char_column = canonical_column\n\n    matcher = difflib.SequenceMatcher(\n        None,\n        canonical_line,\n        source_line,\n        autojunk=False,\n    )\n    for tag, canonical_start, canonical_end, source_start, source_end in matcher.get_opcodes():\n        if canonical_start <= canonical_char_column <= canonical_end:\n            if tag == \"equal\":\n                return source_start + (canonical_char_column - canonical_start)\n            if canonical_char_column == canonical_end:\n                return source_end\n            return source_start\n    return min(canonical_char_column, len(source_line))\n\n\ndef _source_column_for_ast_node(\n    node: ast.AST,\n    canonical_lines: list[str],\n    source_lines: dict[int, str],\n) -> int:\n    \"\"\"Convert an AST node column to the original PT source column.\"\"\"\n    canonical_line = canonical_lines[node.lineno - 1] if node.lineno <= len(canonical_lines) else \"\"\n    source_line = source_lines.get(node.lineno, \"\")\n    return _map_canonical_column_to_source(\n        canonical_line,\n        source_line,\n        getattr(node, \"col_offset\", 0),\n    )\n\n\ndef _all_symbol_tables(table: symtable.SymbolTable) -> list[symtable.SymbolTable]:\n    \"\"\"Flatten a symbol-table tree while preserving source order.\"\"\"\n    resultado = [table]\n    for filho in table.get_children():\n        resultado.extend(_all_symbol_tables(filho))\n    return resultado\n\n\ndef _protected_names(\n    table: symtable.SymbolTable,\n    module_table: symtable.SymbolTable,\n) -> frozenset[str]:\n    \"\"\"Find names whose references must keep the Portuguese spelling.\n\n    ``symtable`` already accounts for assignments, parameters, imports,\n    ``global`` and ``nonlocal`` declarations. A global reference is also\n    protected when the module binds that name, because that binding shadows\n    the injected Portuguese builtin at runtime.\n    \"\"\"\n    protected = set()\n    for name in table.get_identifiers():\n        symbol = table.lookup(name)\n        is_nonlocal = getattr(symbol, \"is_nonlocal\", lambda: False)()\n        if symbol.is_local() or symbol.is_free() or is_nonlocal:\n            protected.add(name)\n            continue\n        if symbol.is_global():\n            if symbol.is_assigned():\n                protected.add(name)\n                continue\n            try:\n                module_symbol = module_table.lookup(name)\n            except KeyError:\n                continue\n            if module_symbol.is_local():\n                protected.add(name)\n    return frozenset(protected)\n\n\ndef _meaningful_token_indices(\n    tokens: list[tokenize.TokenInfo],\n) -> list[int]:\n    \"\"\"Return token indices that can delimit a function signature.\"\"\"\n    ignored = {\n        token.ENCODING,\n        token.NL,\n        token.NEWLINE,\n        token.INDENT,\n        token.DEDENT,\n        token.COMMENT,\n        token.ENDMARKER,\n    }\n    return [idx for idx, tok in enumerate(tokens) if tok.type not in ignored]\n\n\ndef _parameter_binding_indices(\n    node: ast.FunctionDef | ast.AsyncFunctionDef,\n    source_tokens: list[tokenize.TokenInfo],\n) -> set[int]:\n    \"\"\"Locate parameter declaration tokens in the original PT token stream.\"\"\"\n    argument_names = {\n        arg.arg\n        for arg in (\n            *getattr(node.args, \"posonlyargs\", []),\n            *node.args.args,\n            *node.args.kwonlyargs,\n        )\n    }\n    if node.args.vararg:\n        argument_names.add(node.args.vararg.arg)\n    if node.args.kwarg:\n        argument_names.add(node.args.kwarg.arg)\n    if not argument_names:\n        return set()\n\n    meaningful = _meaningful_token_indices(source_tokens)\n    definition_index = None\n    for position, idx in enumerate(meaningful):\n        tok = source_tokens[idx]\n        if tok.start[0] != node.lineno or tok.type != token.NAME:\n            continue\n        if tok.string not in (\"funcao\", \"função\", \"def\"):\n            continue\n        if position + 1 < len(meaningful):\n            next_tok = source_tokens[meaningful[position + 1]]\n            if next_tok.type == token.NAME and next_tok.string == node.name:\n                definition_index = idx\n                break\n    if definition_index is None:\n        return set()\n\n    open_index = None\n    for idx in range(definition_index + 1, len(source_tokens)):\n        tok = source_tokens[idx]\n        if tok.type == token.OP and tok.string == \"(\":\n            open_index = idx\n            break\n        if tok.type in (token.NEWLINE, token.INDENT, token.DEDENT):\n            break\n    if open_index is None:\n        return set()\n\n    depth = 0\n    close_index = None\n    for idx in range(open_index, len(source_tokens)):\n        tok = source_tokens[idx]\n        if tok.type != token.OP:\n            continue\n        if tok.string == \"(\":\n            depth += 1\n        elif tok.string == \")\":\n            depth -= 1\n            if depth == 0:\n                close_index = idx\n                break\n    if close_index is None:\n        return set()\n\n    result = set()\n    segment: list[int] = []\n    nested_depth = 0\n\n    def mark_segment(indices: list[int]) -> None:\n        for candidate_index in indices:\n            candidate = source_tokens[candidate_index]\n            if candidate.type == token.NAME:\n                if candidate.string in argument_names:\n                    result.add(candidate_index)\n                break\n\n    for idx in range(open_index + 1, close_index):\n        tok = source_tokens[idx]\n        if tok.type == token.OP:\n            if tok.string in \"([{\":\n                nested_depth += 1\n            elif tok.string in \")]}\":\n                nested_depth = max(0, nested_depth - 1)\n            elif tok.string == \",\" and nested_depth == 0:\n                mark_segment(segment)\n                segment = []\n                continue\n        segment.append(idx)\n    mark_segment(segment)\n    return result\n\n\ndef _lambda_parameter_binding_indices(\n    node: ast.Lambda,\n    source_tokens: list[tokenize.TokenInfo],\n    canonical_lines: list[str],\n    source_lines: dict[int, str],\n) -> set[int]:\n    \"\"\"Locate lambda parameter declarations in the original PT token stream.\"\"\"\n    argument_names = {\n        arg.arg\n        for arg in (\n            *getattr(node.args, \"posonlyargs\", []),\n            *node.args.args,\n            *node.args.kwonlyargs,\n        )\n    }\n    if node.args.vararg:\n        argument_names.add(node.args.vararg.arg)\n    if node.args.kwarg:\n        argument_names.add(node.args.kwarg.arg)\n    if not argument_names:\n        return set()\n\n    expected_column = _source_column_for_ast_node(\n        node,\n        canonical_lines,\n        source_lines,\n    )\n    lambda_candidates = [\n        idx\n        for idx, tok in enumerate(source_tokens)\n        if tok.type == token.NAME\n        and tok.string == \"lambda\"\n        and tok.start[0] == node.lineno\n    ]\n    if not lambda_candidates:\n        return set()\n    lambda_index = min(\n        lambda_candidates,\n        key=lambda idx: abs(source_tokens[idx].start[1] - expected_column),\n    )\n\n    result = set()\n    segment: list[int] = []\n    nested_depth = 0\n\n    def mark_segment(indices: list[int]) -> None:\n        for candidate_index in indices:\n            candidate = source_tokens[candidate_index]\n            if candidate.type == token.NAME:\n                if candidate.string in argument_names:\n                    result.add(candidate_index)\n                break\n\n    for idx in range(lambda_index + 1, len(source_tokens)):\n        tok = source_tokens[idx]\n        if tok.type == token.OP:\n            if tok.string in \"([{\":\n                nested_depth += 1\n            elif tok.string in \")]}\":\n                nested_depth = max(0, nested_depth - 1)\n            elif tok.string == \",\" and nested_depth == 0:\n                mark_segment(segment)\n                segment = []\n                continue\n            elif tok.string == \":\" and nested_depth == 0:\n                mark_segment(segment)\n                break\n        segment.append(idx)\n    return result\n\n\ndef build_scope_context(\n    canonical_syntax: str,\n    source_tokens: list[tokenize.TokenInfo],\n) -> tuple[list[ScopeInfo], set[int], frozenset[str]]:\n    \"\"\"Build lexical binding context for canonical builtin substitution.\"\"\"\n    try:\n        tree = ast.parse(canonical_syntax)\n        module_table = symtable.symtable(canonical_syntax, \"<codigo_pt>\", \"exec\")\n    except (SyntaxError, ValueError):\n        return [], set(), frozenset()\n\n    canonical_lines = canonical_syntax.splitlines()\n    source_lines = {\n        tok.start[0]: tok.line\n        for tok in source_tokens\n        if tok.line is not None\n    }\n    tables_by_key: dict[tuple[str, str, int], list[symtable.SymbolTable]] = {}\n    for table in _all_symbol_tables(module_table):\n        key = (table.get_type(), table.get_name(), table.get_lineno())\n        tables_by_key.setdefault(key, []).append(table)\n\n    scopes = []\n    parameter_indices = set()\n    for node in ast.walk(tree):\n        key = _scope_key(node)\n        span = _scope_span(node)\n        if key is None or span is None:\n            continue\n        matching_tables = tables_by_key.get(key, [])\n        if not matching_tables:\n            continue\n        table = matching_tables.pop(0)\n        start_node, start_line, end_line = span\n        scopes.append(\n            ScopeInfo(\n                start_line=start_line,\n                start_column=_source_column_for_ast_node(\n                    start_node,\n                    canonical_lines,\n                    source_lines,\n                ),\n                end_line=end_line,\n                protected_names=_protected_names(table, module_table),\n            )\n        )\n        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):\n            parameter_indices.update(_parameter_binding_indices(node, source_tokens))\n        elif isinstance(node, ast.Lambda):\n            parameter_indices.update(\n                _lambda_parameter_binding_indices(\n                    node,\n                    source_tokens,\n                    canonical_lines,\n                    source_lines,\n                )\n            )\n\n    return scopes, parameter_indices, _protected_names(module_table, module_table)\n",
  "transpiler.py": "\"\"\"\nTranspilador PT -> Python baseado no módulo `tokenize` da stdlib.\n\nEstratégia: em vez de escrever um parser do zero, usamos o tokenizer\ndo próprio Python para separar o código em tokens, trocamos apenas o\ntexto dos tokens NAME que constam no dicionário, e remontamos com\n`tokenize.untokenize`. Isso significa que strings, comentários,\nnúmeros e indentação nunca são tocados -- só identificadores que\nbatem exatamente com uma entrada do dicionário.\n\"\"\"\n\nfrom __future__ import annotations\n\nimport io\nimport keyword\nimport token\nimport tokenize\n\nfrom .dicionario import MAPA, BUILTINS_CANONICOS\nfrom .escopo_canonico import ScopeInfo, build_scope_context\n\n\nclass ErroDeTraducao(Exception):\n    \"\"\"Erro ao tentar transpilar o código-fonte em português.\"\"\"\n\n\n# FSTRING_MIDDLE só existe no Python 3.12+ (PEP 701). Nas versões anteriores a\n# f-string é um único token STRING, então usamos um sentinela que nunca casa.\n_FSTRING_MIDDLE = getattr(token, \"FSTRING_MIDDLE\", -1)\n\n\nASSIGNMENT_OPERATORS = {\n    \"=\", \":=\", \"+=\", \"-=\", \"*=\", \"/=\", \"//=\", \"%=\", \"**=\",\n    \"<<=\", \">>=\", \"&=\", \"|=\", \"^=\", \"@=\",\n}\n\n\ndef _has_assignment_until_statement_end(\n    tokens: list[tokenize.TokenInfo], start: int,\n) -> bool:\n    \"\"\"Check whether an assignment operator appears before the statement ends.\n\n    No Python 3.12+ (PEP 701) o marcador de depuração de f-string ``f\"{expr=}\"``\n    aparece como um token ``OP '='`` no fluxo. Ele não é uma atribuição: é\n    seguido de ``}`` (ou de ``!`` de conversão / ``:`` de format spec). Ignorá-lo\n    evita tratar o builtin à esquerda como alvo de atribuição e deixá-lo sem\n    tradução na exportação canônica.\n    \"\"\"\n    resto = tokens[start + 1:]\n    nesting = 0\n    for pos, tok in enumerate(resto):\n        if tok.type == token.OP:\n            if tok.string in \"([{\":\n                nesting += 1\n            elif tok.string in \")]}\":\n                nesting = max(0, nesting - 1)\n            elif tok.string == \"=\" and nesting == 0:\n                # '=' de depuração de f-string: seguido de '}', '!' ou ':'.\n                # No 3.12+, o format spec após o '=' surge como FSTRING_MIDDLE.\n                proximo = resto[pos + 1] if pos + 1 < len(resto) else None\n                tipos_sufixo_debug = (token.OP, _FSTRING_MIDDLE)\n                if (\n                    proximo is not None\n                    and proximo.type in tipos_sufixo_debug\n                    and proximo.string[:1] in (\"}\", \"!\", \":\")\n                ):\n                    continue\n                return True\n            elif tok.string in ASSIGNMENT_OPERATORS and nesting == 0:\n                return True\n        elif tok.type == token.NEWLINE and nesting == 0:\n            return False\n    return False\n\n\nSINGLETONS_DE_IDENTIDADE = {\"nulo\", \"None\", \"verdadeiro\", \"falso\", \"True\", \"False\"}\n\n\ndef _substitui_em_fstring(\n    literal_fstring: str,\n    protected_names: frozenset[str] = frozenset(),\n) -> str:\n    \"\"\"Traduz expressões interpoladas dentro de f-strings para Python canônico.\"\"\"\n    quote_idx = -1\n    for idx, c in enumerate(literal_fstring[:4]):\n        if c in ('\"', \"'\"):\n            quote_idx = idx\n            break\n    if quote_idx == -1:\n        return literal_fstring\n\n    prefixo = literal_fstring[:quote_idx].lower()\n    if \"f\" not in prefixo:\n        return literal_fstring\n\n    delimitador = literal_fstring[quote_idx:]\n    if delimitador.startswith(('\"\"\"', \"'''\")):\n        quotes = delimitador[:3]\n        miolo = delimitador[3:-3]\n    else:\n        quotes = delimitador[:1]\n        miolo = delimitador[1:-1]\n\n    resultado = []\n    i = 0\n    n = len(miolo)\n    while i < n:\n        if miolo[i : i + 2] == \"{{\":\n            resultado.append(\"{{\")\n            i += 2\n            continue\n        if miolo[i : i + 2] == \"}}\":\n            resultado.append(\"}}\")\n            i += 2\n            continue\n        if miolo[i] == \"{\":\n            inicio = i + 1\n            nivel_chaves = 0\n            nivel_paren = 0\n            nivel_colch = 0\n            em_aspas = None\n            j = inicio\n            # Fim da expressão de código dentro do campo (antes de sufixos\n            # como o '=' de depuração, a conversão '!r' ou o format spec ':').\n            fim_expr = -1\n            # Sufixo preservado literalmente: '=' de depuração + '!conv' + ':spec'.\n            sufixo = \"\"\n            while j < n:\n                ch = miolo[j]\n                if em_aspas:\n                    if ch == \"\\\\\" and j + 1 < n:\n                        j += 2\n                        continue\n                    if ch == em_aspas:\n                        em_aspas = None\n                else:\n                    if ch in ('\"', \"'\"):\n                        em_aspas = ch\n                    elif ch == \"(\":\n                        nivel_paren += 1\n                    elif ch == \")\":\n                        nivel_paren = max(0, nivel_paren - 1)\n                    elif ch == \"[\":\n                        nivel_colch += 1\n                    elif ch == \"]\":\n                        nivel_colch = max(0, nivel_colch - 1)\n                    elif ch == \"{\":\n                        nivel_chaves += 1\n                    elif ch == \"}\":\n                        if nivel_chaves == 0 and nivel_paren == 0 and nivel_colch == 0:\n                            break\n                        nivel_chaves -= 1\n                    elif (\n                        nivel_chaves == 0\n                        and nivel_paren == 0\n                        and nivel_colch == 0\n                    ):\n                        # '=' de depuração (PEP: f\"{expr=}\"): um '=' isolado, não\n                        # parte de '==', '!=', '<=', '>=', ':='. Marca o fim da\n                        # expressão; tudo dali em diante é preservado literal.\n                        if (\n                            ch == \"=\"\n                            and miolo[j + 1 : j + 2] != \"=\"\n                            and miolo[j - 1 : j] not in (\"=\", \"!\", \"<\", \">\", \":\")\n                        ):\n                            fim_expr = j\n                            k = j\n                            while k < n and miolo[k] != \"}\":\n                                k += 1\n                            sufixo = miolo[j:k]\n                            j = k\n                            break\n                        # Conversão '!r'/'!s'/'!a', só quando seguida de '}' ou ':'\n                        # (evita confundir com o operador '!=').\n                        if (\n                            ch == \"!\"\n                            and miolo[j + 1 : j + 2] in (\"r\", \"s\", \"a\")\n                            and miolo[j + 2 : j + 3] in (\"}\", \":\")\n                        ):\n                            fim_expr = j\n                            k = j\n                            while k < n and miolo[k] != \"}\":\n                                k += 1\n                            sufixo = miolo[j:k]\n                            j = k\n                            break\n                        # Início do format spec ':' no nível do campo.\n                        if ch == \":\":\n                            fim_expr = j\n                            k = j\n                            while k < n and miolo[k] != \"}\":\n                                k += 1\n                            sufixo = miolo[j:k]\n                            j = k\n                            break\n                j += 1\n\n            if fim_expr == -1:\n                fim_expr = j\n            expr_bruta = miolo[inicio:fim_expr]\n\n            try:\n                expr_traduzida = _transpila_core(\n                    expr_bruta,\n                    traduzir_builtins=True,\n                    protected_names=protected_names,\n                ).strip()\n            except Exception:\n                expr_traduzida = expr_bruta\n\n            resultado.append(\"{\" + expr_traduzida + sufixo + \"}\")\n            i = j + 1\n        else:\n            resultado.append(miolo[i])\n            i += 1\n\n    return literal_fstring[:quote_idx] + quotes + \"\".join(resultado) + quotes\n\n\n\ndef _transpila_core(\n    codigo_pt: str,\n    traduzir_builtins: bool = False,\n    protected_names: frozenset[str] | None = None,\n) -> str:\n    \"\"\"Núcleo de tradução léxica PT -> Python com controle de tradução de builtins.\"\"\"\n    tokens_saida = []\n    leitor = io.StringIO(codigo_pt).readline\n\n    try:\n        fluxo = list(tokenize.generate_tokens(leitor))\n    except (tokenize.TokenError, IndentationError) as exc:\n        raise ErroDeTraducao(f\"Não consegui interpretar o código: {exc}\") from exc\n\n    scope_infos: list[ScopeInfo] = []\n    parameter_indices: set[int] = set()\n    inherited_protected_names = protected_names or frozenset()\n    module_protected_names = inherited_protected_names\n    if traduzir_builtins:\n        canonical_syntax = _transpila_core(codigo_pt, traduzir_builtins=False)\n        (\n            scope_infos,\n            parameter_indices,\n            discovered_module_names,\n        ) = build_scope_context(\n            canonical_syntax,\n            fluxo,\n        )\n        module_protected_names = inherited_protected_names | discovered_module_names\n\n    def names_protected_for(tok: tokenize.TokenInfo) -> frozenset[str]:\n        candidates = [\n            scope\n            for scope in scope_infos\n            if scope.start_line <= tok.start[0] <= scope.end_line\n            and (\n                tok.start[0] > scope.start_line\n                or tok.start[1] >= scope.start_column\n            )\n        ]\n        if not candidates:\n            return module_protected_names\n        return inherited_protected_names | max(\n            candidates,\n            key=lambda scope: (scope.start_column, scope.start_line),\n        ).protected_names\n\n    i = 0\n    n = len(fluxo)\n\n    while i < n:\n        tok = fluxo[i]\n        tipo, valor, inicio, fim, linha = tok\n\n        # Se for precedido por '.', é acesso ou definição de atributo (ex.: obj.se, self.tipo = 1)\n        # e não deve sofrer substituição nem checagem de palavra reservada.\n        anterior = fluxo[i - 1] if i > 0 else None\n        eh_atributo = anterior is not None and anterior.type == token.OP and anterior.string == \".\"\n\n        if tipo == token.NAME and not eh_atributo:\n            proximo = fluxo[i + 1] if i + 1 < n else None\n            proximo_2 = fluxo[i + 2] if i + 2 < n else None\n\n            # Reconhece \"senao se\" ou \"senão se\" na mesma linha e funde em \"elif\"\n            if (\n                valor in (\"senao\", \"senão\")\n                and proximo is not None\n                and proximo.type == token.NAME\n                and proximo.string == \"se\"\n                and proximo.start[0] == inicio[0]\n            ):\n                if _has_assignment_until_statement_end(fluxo, i):\n                    raise ErroDeTraducao(\n                        f\"linha {inicio[0]}: '{valor} se' é uma palavra reservada nesta \"\n                        f\"linguagem (equivale a 'elif' em Python) e não pode \"\n                        f\"ser usada como nome de variável.\"\n                    )\n                tokens_saida.append((token.NAME, \"elif\"))\n                i += 2\n                continue\n\n            # Reconhece negação composta \"nao eh\" ou \"não é\" na mesma linha\n            if (\n                valor in (\"nao\", \"não\")\n                and proximo is not None\n                and proximo.type == token.NAME\n                and proximo.string in (\"eh\", \"é\")\n                and proximo.start[0] == inicio[0]\n            ):\n                if _has_assignment_until_statement_end(fluxo, i):\n                    raise ErroDeTraducao(\n                        f\"linha {inicio[0]}: '{valor} {proximo.string}' é uma expressão reservada nesta \"\n                        f\"linguagem e não pode ser usada como nome de variável.\"\n                    )\n                if proximo_2 is not None and proximo_2.string in SINGLETONS_DE_IDENTIDADE:\n                    tokens_saida.append((token.NAME, \"is\"))\n                    tokens_saida.append((token.NAME, \"not\"))\n                else:\n                    tokens_saida.append((token.OP, \"!=\"))\n                i += 2\n                continue\n\n            # Resolução contextual de \"eh\" e \"é\" (ADR-002)\n            if valor in (\"eh\", \"é\"):\n                if _has_assignment_until_statement_end(fluxo, i):\n                    raise ErroDeTraducao(\n                        f\"linha {inicio[0]}: '{valor}' é uma palavra reservada nesta \"\n                        f\"linguagem e não pode ser usada como nome de variável.\"\n                    )\n                if proximo is not None and proximo.string in SINGLETONS_DE_IDENTIDADE:\n                    tokens_saida.append((token.NAME, \"is\"))\n                else:\n                    tokens_saida.append((token.OP, \"==\"))\n                i += 1\n                continue\n\n            if valor in MAPA:\n                # Checagem amigável: usar uma palavra reservada como alvo de\n                # atribuição (\"para = 5\") gera um SyntaxError confuso depois\n                # da tradução. Detectamos aqui e explicamos o motivo real.\n                if _has_assignment_until_statement_end(fluxo, i):\n                    raise ErroDeTraducao(\n                        f\"linha {inicio[0]}: '{valor}' é uma palavra reservada nesta \"\n                        f\"linguagem (equivale a '{MAPA[valor]}' em Python) e não pode \"\n                        f\"ser usada como nome de variável. Escolha outro nome, \"\n                        f\"ex.: '{valor}_valor'.\"\n                    )\n                valor = MAPA[valor]\n            elif traduzir_builtins and valor in BUILTINS_CANONICOS:\n                # Na exportação canônica, substitui builtins pedagógicos por seus equivalentes Python.\n                # Mantém identificadores vinculados ao escopo atual, preservando\n                # o comportamento normal de sombreamento de nomes em Python.\n                eh_definicao_funcao = anterior is not None and anterior.type == token.NAME and anterior.string in (\"def\", \"funcao\", \"função\")\n                eh_alvo_atribuicao = _has_assignment_until_statement_end(fluxo, i)\n                eh_nome_vinculado = (\n                    i in parameter_indices\n                    or valor in names_protected_for(tok)\n                )\n                \n                # Tipos embutidos (\"lista\", \"conjunto\", \"tupla\", etc.) só viram \"list\", \"set\", etc.\n                # se forem chamados como construtores com '(' ou usados em anotação de tipo.\n                # Caso contrário, representam variáveis do aluno (ex.: tamanho(lista)).\n                eh_tipo_embutido = valor in (\"lista\", \"dicionario\", \"dicionário\", \"conjunto\", \"tupla\", \"texto\", \"inteiro\", \"decimal\", \"booleano\")\n                eh_chamada_ou_anotacao = (proximo is not None and proximo.string == \"(\") or (anterior is not None and anterior.string in (\":\", \"->\", \"[\"))\n                \n                if (\n                    not eh_definicao_funcao\n                    and not eh_alvo_atribuicao\n                    and not eh_nome_vinculado\n                ):\n                    if not eh_tipo_embutido or eh_chamada_ou_anotacao:\n                        valor = BUILTINS_CANONICOS[valor]\n\n        elif tipo == token.STRING and traduzir_builtins:\n            valor = _substitui_em_fstring(\n                valor,\n                names_protected_for(tok),\n            )\n\n        tokens_saida.append((tipo, valor))\n        i += 1\n\n\n    try:\n        return tokenize.untokenize(tokens_saida)\n    except ValueError as exc:\n        raise ErroDeTraducao(f\"Falha ao remontar o código traduzido: {exc}\") from exc\n\n\ndef transpila(codigo_pt: str) -> str:\n    \"\"\"Converte código-fonte em português para código Python equivalente.\n\n    Preserva números de linha 1:1 com o original, o que permite que\n    tracebacks apontem para a linha certa do arquivo .ptpy do usuário.\n    \"\"\"\n    return _transpila_core(codigo_pt, traduzir_builtins=False)\n\n\ndef transpila_canonico(codigo_pt: str) -> str:\n    \"\"\"Converte código-fonte em português para código Python canônico e autônomo (ADR-003).\n\n    Substitui tanto a sintaxe estrutural quanto nomes de funções embutidas (mostre -> print,\n    tamanho -> len, etc.), permitindo execução pura sem necessidade do pacote transpilador_pt.\n    \"\"\"\n    return _transpila_core(codigo_pt, traduzir_builtins=True)\n\n\ndef palavra_e_reservada_em_pt(nome: str) -> bool:\n    \"\"\"Útil para avisar o usuário se ele tentar nomear uma variável\n    com uma palavra que é reservada nesta camada (ex.: 'para', 'em', 'eh').\"\"\"\n    return nome in MAPA or nome in (\"eh\", \"é\") or keyword.iskeyword(nome)\n",
  "transicao.py": "\"\"\"Módulo de transição pedagógica bilíngue (Português -> Python Canônico).\n\nFornece renderização visual comparativa lado a lado com numeração de linhas,\npermitindo ao estudante entender a correspondência direta entre as linguagens.\n\"\"\"\n\nfrom __future__ import annotations\n\nimport itertools\nimport shutil\n\n\ndef _trunca(texto: str, largura: int) -> str:\n    \"\"\"Trunca o texto caso exceda a largura permitida, adicionando reticências.\"\"\"\n    if len(texto) <= largura:\n        return texto\n    if largura <= 3:\n        return texto[:largura]\n    return texto[: largura - 1] + \"…\"\n\n\ndef _renderiza_empilhado(\n    codigo_pt: str,\n    codigo_py: str,\n    largura_terminal: int,\n) -> str:\n    \"\"\"Renderiza cada idioma em sua própria seção em terminais estreitos.\"\"\"\n    largura = max(1, largura_terminal)\n    linhas_pt = codigo_pt.splitlines()\n    linhas_py = codigo_py.splitlines()\n    total_linhas = max(len(linhas_pt), len(linhas_py), 1)\n    largura_num = max(1, len(str(total_linhas)))\n\n    def renderiza_secao(titulo: str, linhas: list[str]) -> list[str]:\n        resultado = [_trunca(titulo, largura)]\n        for idx, linha in enumerate(linhas, start=1):\n            prefixo = f\"{idx:>{largura_num}} │ \"\n            resultado.append(\n                _trunca(\n                    prefixo + _trunca(linha, max(1, largura - len(prefixo))),\n                    largura,\n                )\n            )\n        return resultado\n\n    aviso = \"Aviso: terminal estreito; colunas empilhadas e linhas truncadas.\"\n    linhas_saida = [_trunca(aviso, largura)]\n    linhas_saida.extend(renderiza_secao(\"Código em Português\", linhas_pt))\n    linhas_saida.extend(renderiza_secao(\"Python Canônico\", linhas_py))\n    return \"\\n\".join(linhas_saida)\n\n\ndef renderiza_lado_a_lado(\n    codigo_pt: str,\n    codigo_py: str,\n    largura_terminal: int | None = None,\n) -> str:\n    \"\"\"Renderiza os códigos em português e Python canônico lado a lado em duas colunas.\n\n    Args:\n        codigo_pt: Código-fonte original em português.\n        codigo_py: Código Python canônico gerado.\n        largura_terminal: Largura total em colunas (obtida dinamicamente se None).\n\n    Returns:\n        String formatada com tabela comparativa pronta para exibição no terminal.\n    \"\"\"\n    if largura_terminal is None:\n        largura_terminal = shutil.get_terminal_size(fallback=(80, 24)).columns\n\n    largura_terminal = max(1, largura_terminal)\n    if largura_terminal < 60:\n        return _renderiza_empilhado(codigo_pt, codigo_py, largura_terminal)\n\n    linhas_pt = codigo_pt.splitlines()\n    linhas_py = codigo_py.splitlines()\n    total_linhas = max(len(linhas_pt), len(linhas_py), 1)\n\n    largura_num = max(3, len(str(total_linhas)))\n    largura_col_num = max(largura_num, len(\"Linha\"))\n    # Formato de cada linha: ' {num} │ {pt} │ {py}'\n    # Espaço consumido por margens e separadores: largura_col_num + 7.\n    largura_fixa = largura_col_num + 7\n    espaco_colunas = max(20, largura_terminal - largura_fixa)\n    largura_col_pt = espaco_colunas // 2\n    largura_col_py = espaco_colunas - largura_col_pt\n\n    # Títulos das colunas\n    titulo_pt = \"Código em Português\" if largura_col_pt >= 20 else \"Português\"\n    titulo_py = \"Python Canônico\" if largura_col_py >= 16 else \"Python\"\n\n    cabecalho_num = f\"{'Linha':>{largura_col_num}}\"\n    cabecalho_pt = f\"{titulo_pt:<{largura_col_pt}}\"\n    cabecalho_py = f\"{titulo_py:<{largura_col_py}}\"\n\n    cabecalho = f\" {cabecalho_num} │ {cabecalho_pt} │ {cabecalho_py}\"\n    divisor = f\"{'─' * (largura_col_num + 2)}┼{'─' * (largura_col_pt + 2)}┼{'─' * (largura_col_py + 1)}\"\n\n    linhas_saida = [cabecalho, divisor]\n\n    for idx, (l_pt, l_py) in enumerate(\n        itertools.zip_longest(linhas_pt, linhas_py, fillvalue=\"\"),\n        start=1,\n    ):\n        num_str = f\"{idx:>{largura_col_num}}\"\n        col_pt = _trunca(l_pt, largura_col_pt)\n        col_py = _trunca(l_py, largura_col_py)\n        linha_formatada = (\n            f\" {num_str} │ {col_pt:<{largura_col_pt}} │ {col_py:<{largura_col_py}}\"\n        )\n        linhas_saida.append(linha_formatada)\n\n    return \"\\n\".join(linhas_saida)\n",
  "erros.py": "\"\"\"\nTradução de erros comuns.\n\nEsta é a parte do projeto com maior retorno pedagógico: a maioria da\nfrustração de um iniciante não vem das ~30 palavras-chave, vem de não\nentender o que uma mensagem de erro em inglês está dizendo. Cobrir os\n20-30 padrões de erro mais comuns já resolve a maior parte da dor real.\n\nCada entrada é (TipoDeExcecao, regex sobre str(exc)) -> função que\ngera a mensagem em português. Os padrões são checados em ordem; o\nprimeiro que casar vence.\n\"\"\"\n\nfrom __future__ import annotations\n\nimport re\nfrom difflib import SequenceMatcher\nfrom typing import Callable\n\nRegra = tuple[type[BaseException], re.Pattern, Callable[[re.Match], str]]\n\n\ndef _regra(excecao: type[BaseException], padrao: str, gerador: Callable[[re.Match], str]) -> Regra:\n    return (excecao, re.compile(padrao), gerador)\n\n\nREGRAS: list[Regra] = [\n    _regra(\n        IndexError, r\"list index out of range\",\n        lambda m: \"Você tentou acessar uma posição que não existe na lista \"\n                  \"(o índice é maior que a quantidade de itens, ou a lista está vazia). \"\n                  \"Lembre-se: a primeira posição é a 0, não a 1.\",\n    ),\n    _regra(\n        IndexError, r\"string index out of range\",\n        lambda m: \"Você tentou acessar uma posição que não existe no texto \"\n                  \"(o índice é maior que a quantidade de caracteres).\",\n    ),\n    _regra(\n        KeyError, r\".*\",\n        lambda m: f\"Você tentou acessar a chave {m.group(0)} num dicionário, \"\n                  \"mas essa chave não existe nele.\",\n    ),\n    _regra(\n        ZeroDivisionError, r\"(?:division by zero|integer division or modulo by zero)\",\n        lambda m: \"Você tentou dividir um número por zero, o que não é permitido.\",\n    ),\n    _regra(\n        TypeError, r\"'([^']+)' not supported between instances of '([^']+)' and '([^']+)'\",\n        lambda m: f\"Você tentou comparar valores com o operador {m.group(1)}, mas os tipos \"\n                  f\"{m.group(2)} e {m.group(3)} não são compatíveis.\",\n    ),\n    _regra(\n        TypeError, r\"unsupported operand type\\(s\\) for \\+: '(\\w+)' and '(\\w+)'\",\n        lambda m: f\"Você tentou somar um valor do tipo {m.group(1)} com um do \"\n                  f\"tipo {m.group(2)}. Provavelmente precisa converter um deles \"\n                  \"antes (ex.: com 'texto(...)' ou 'inteiro(...)').\",\n    ),\n    _regra(\n        TypeError, r'can only concatenate str \\(not \"(\\w+)\"\\) to str',\n        lambda m: f\"Você tentou juntar (+) um texto com um valor do tipo \"\n                  f\"{m.group(1)}. Para juntar os dois, converta o valor para \"\n                  \"texto primeiro, ex.: 'texto(numero)'.\",\n    ),\n    _regra(\n        TypeError, r\"'(\\w+)' object is not subscriptable\",\n        lambda m: f\"Você tentou acessar uma posição (com [ ]) de algo do tipo \"\n                  f\"{m.group(1)}, mas esse tipo não permite isso.\",\n    ),\n    _regra(\n        TypeError, r\"object of type '([^']+)' has no len\\(\\)\",\n        lambda m: f\"Você tentou descobrir o tamanho de um valor do tipo {m.group(1)}, \"\n                  \"mas esse tipo não possui tamanho. Use 'tamanho(...)' apenas em textos \"\n                  \"ou coleções.\",\n    ),\n    _regra(\n        TypeError, r\"'([^']+)' object is not callable\",\n        lambda m: f\"Você tentou chamar um valor do tipo {m.group(1)} como se fosse uma função. \"\n                  \"Confira se escreveu o nome correto.\",\n    ),\n    _regra(\n        TypeError, r\"(\\w+)\\(\\) missing (\\d+) required positional arguments?\",\n        lambda m: f\"A função '{m.group(1)}' precisa de {m.group(2)} argumento(s) \"\n                  \"a mais do que você passou.\",\n    ),\n    _regra(\n        TypeError, r\"(\\w+)\\(\\) takes (\\d+) positional argument.* but (\\d+) (?:were|was) given\",\n        lambda m: f\"A função '{m.group(1)}' espera {m.group(2)} argumento(s), \"\n                  f\"mas você passou {m.group(3)}.\",\n    ),\n    _regra(\n        AttributeError, r\"'(\\w+)' object has no attribute '(\\w+)'\",\n        lambda m: f\"Um valor do tipo {m.group(1)} não tem '{m.group(2)}'. \"\n                  \"Confira se digitou o nome certo ou se é o tipo de objeto esperado.\",\n    ),\n    _regra(\n        UnboundLocalError, r\"cannot access local variable '([^']+)'\",\n        lambda m: f\"A variável local '{m.group(1)}' foi usada antes de receber um valor. \"\n                  \"Atribua um valor a ela antes de tentar usá-la.\",\n    ),\n    _regra(\n        NameError, r\"name '(\\w+)' is not defined\",\n        lambda m: f\"A variável ou função '{m.group(1)}' foi usada antes de existir. \"\n                  \"Confira se você não esqueceu de criá-la antes, ou se digitou \"\n                  \"o nome certo (lembre-se que maiúsculas/minúsculas importam).\",\n    ),\n    _regra(\n        ValueError, r\"invalid literal for int\\(\\) with base 10: '(.*)'\",\n        lambda m: f\"Você tentou converter \\\"{m.group(1)}\\\" para número inteiro, \"\n                  \"mas esse texto não representa um número inteiro válido.\",\n    ),\n    _regra(\n        ValueError, r\"could not convert string to float: '([^']*)'\",\n        lambda m: f\"Você tentou converter \\\"{m.group(1)}\\\" para número decimal, \"\n                  \"mas esse texto não representa um número válido.\",\n    ),\n    _regra(\n        ModuleNotFoundError, r\"No module named '([^']+)'\",\n        lambda m: f\"O módulo '{m.group(1)}' não foi encontrado. Confira o nome \"\n                  \"ou se ele precisa ser instalado.\",\n    ),\n    _regra(\n        RecursionError, r\".*\",\n        lambda m: \"Sua função está chamando a si mesma sem parar \"\n                  \"(ela nunca chega numa condição de parada).\",\n    ),\n    _regra(\n        IndentationError, r\"expected an indented block\",\n        lambda m: \"O Python esperava que esta linha estivesse com recuo (espaços/indentação) \"\n                  \"para a direita, pois ela faz parte do bloco acima. Use 4 espaços ou Tab.\",\n    ),\n    _regra(\n        IndentationError, r\"unindent does not match any outer indentation level\",\n        lambda m: \"A indentação desta linha não está alinhada com nenhuma linha anterior. \"\n                  \"Verifique os espaços no início da linha para alinhar com o bloco correspondente.\",\n    ),\n    _regra(\n        SyntaxError, r\"expected ':'\",\n        lambda m: \"Esta instrução precisa terminar com dois pontos (:). \"\n                  \"Eles indicam o início do bloco recuado.\",\n    ),\n    _regra(\n        SyntaxError, r\"unexpected EOF while parsing\",\n        lambda m: \"O código terminou antes do esperado. Confira se você não esqueceu \"\n                  \"de fechar algum parêntese, colchete ou aspas.\",\n    ),\n    _regra(\n        SyntaxError,\n        r\"(?:EOL while scanning string literal|unterminated string literal|unterminated triple-quoted string literal)\",\n        lambda m: \"Você abriu aspas para um texto, mas esqueceu de fechar antes do fim da linha.\",\n    ),\n    _regra(\n        SyntaxError, r\"invalid syntax\",\n        lambda m: \"Erro de escrita no código. Confira se você não esqueceu de colocar \"\n                  \"dois pontos (:) no final da linha ou se digitou algo fora de ordem.\",\n    ),\n]\n\n\ndef traduz_excecao(exc: BaseException) -> str | None:\n    \"\"\"Retorna uma explicação em português para a exceção, ou None se\n    nenhuma regra conhecida bater (nesse caso, mostre o erro original).\"\"\"\n    texto_busca = exc.msg if isinstance(exc, SyntaxError) and getattr(exc, \"msg\", None) else str(exc)\n    for tipo, padrao, gerador in REGRAS:\n        if isinstance(exc, tipo):\n            casamento = padrao.search(texto_busca)\n            if casamento:\n                return gerador(casamento)\n    return None\n\n\ndef _map_generated_column_to_source(column: int, source_line: str, generated_line: str) -> int:\n    \"\"\"Map a column from translated Python back to the original source line.\"\"\"\n    generated_position = max(0, column - 1)\n    opcodes = SequenceMatcher(\n        None, source_line, generated_line, autojunk=False,\n    ).get_opcodes()\n\n    # A replacement can be followed by a deletion when untokenize adds spacing.\n    # A parser position after the translated text then maps to the source end.\n    for tag, source_start, source_end, generated_start, generated_end in opcodes:\n        if tag == \"delete\" and generated_start == generated_end == generated_position:\n            return source_end + 1\n\n    for tag, source_start, source_end, generated_start, generated_end in opcodes:\n        if generated_start <= generated_position <= generated_end:\n            if tag == \"equal\":\n                return source_start + (generated_position - generated_start) + 1\n            if tag == \"replace\":\n                if generated_position == generated_end:\n                    return source_end + 1\n                if generated_position == generated_start:\n                    return source_start + 1\n                ratio = (generated_position - generated_start) / max(\n                    1, generated_end - generated_start,\n                )\n                return round(source_start + ratio * (source_end - source_start)) + 1\n            return source_start + 1\n\n    return min(generated_position, len(source_line)) + 1\n\n\ndef formata_erro_amigavel(\n    exc: BaseException,\n    linhas_fonte_pt: list[str],\n    linhas_fonte_py: list[str] | None = None,\n) -> str:\n    \"\"\"Monta uma mensagem de erro amigável apontando para a linha do\n    arquivo .ptpy original (não do Python gerado internamente).\"\"\"\n    linha_numero = None\n    coluna = None\n\n    if isinstance(exc, SyntaxError):\n        linha_numero = exc.lineno\n        coluna = exc.offset\n    else:\n        tb = exc.__traceback__\n        # Anda até o último frame que pertence ao código do usuário\n        # (compilado com o nome de arquivo especial \"<codigo_pt>\")\n        while tb is not None:\n            if tb.tb_frame.f_code.co_filename == \"<codigo_pt>\":\n                linha_numero = tb.tb_lineno\n            tb = tb.tb_next\n\n    partes = [f\"⚠️  Deu erro do tipo: {type(exc).__name__}\"]\n    if linha_numero and 1 <= linha_numero <= len(linhas_fonte_pt):\n        trecho = linhas_fonte_pt[linha_numero - 1]\n        prefixo_trecho = f\"   Na linha {linha_numero}: \"\n        partes.append(prefixo_trecho + trecho.strip())\n        if coluna is not None and coluna > 0:\n            if linhas_fonte_py and linha_numero <= len(linhas_fonte_py):\n                coluna = _map_generated_column_to_source(\n                    coluna,\n                    trecho,\n                    linhas_fonte_py[linha_numero - 1],\n                )\n            recuo_original = len(trecho) - len(trecho.lstrip())\n            coluna_ajustada = max(1, coluna - recuo_original)\n            partes.append(\" \" * len(prefixo_trecho) + \" \" * (coluna_ajustada - 1) + \"^\")\n\n    explicacao = traduz_excecao(exc)\n    if explicacao:\n        partes.append(f\"   {explicacao}\")\n    else:\n        partes.append(f\"   Detalhe técnico (ainda sem tradução): {exc}\")\n\n    return \"\\n\".join(partes)\n",
  "executor.py": "from __future__ import annotations\n\nimport sys\n\nfrom .dicionario import BUILTINS_PT\nfrom .erros import formata_erro_amigavel\nfrom .transpiler import ErroDeTraducao, transpila\n\n\ndef executa_codigo(codigo_pt: str, mostrar_python: bool = False) -> int:\n    \"\"\"Traduz e executa código-fonte em português no processo Python atual.\n\n    Segurança (decisão deliberada): a execução NÃO é isolada. O código roda com\n    `exec` no mesmo processo e com acesso aos builtins reais do Python (além dos\n    curados em `BUILTINS_PT`), permitindo `importe`, entrada/saída e acesso ao\n    sistema de arquivos — recursos necessários à missão pedagógica de servir como\n    rampa para o Python real (ver ADR-001/003). Restringir `__builtins__` daria\n    apenas uma falsa sensação de sandbox (é contornável) e mutilaria esses\n    recursos. Destina-se a scripts locais confiáveis, como `python3 arquivo.py`.\n    O isolamento de verdade fica a cargo do playground web, onde o Pyodide roda\n    em WebAssembly, fora do sistema do usuário. Ver também o aviso no README.\n    \"\"\"\n    linhas_fonte_pt = codigo_pt.splitlines()\n\n    try:\n        codigo_python = transpila(codigo_pt)\n    except ErroDeTraducao as exc:\n        print(f\"⚠️  Erro ao traduzir seu código: {exc}\", file=sys.stderr)\n        return 1\n\n    if mostrar_python:\n        print(\"--- código Python gerado ---\")\n        print(codigo_python)\n        print(\"----------------------------\")\n\n    try:\n        # nome de arquivo especial: é assim que formata_erro_amigavel\n        # reconhece qual frame do traceback pertence ao código do usuário\n        compilado = compile(codigo_python, \"<codigo_pt>\", \"exec\")\n        # Sem '__builtins__' restrito: o Python injeta os builtins reais, o que é\n        # intencional (não é sandbox). Ver a docstring da função para o porquê.\n        contexto = {\"__name__\": \"__main__\", **BUILTINS_PT}\n        exec(compilado, contexto)\n    except Exception as exc:\n        print(\n            formata_erro_amigavel(exc, linhas_fonte_pt, codigo_python.splitlines()),\n            file=sys.stderr,\n        )\n        return 1\n\n    return 0\n\n\ndef executa_arquivo(caminho: str, mostrar_python: bool = False) -> int:\n    try:\n        with open(caminho, \"r\", encoding=\"utf-8\") as f:\n            codigo_pt = f.read()\n    except (OSError, UnicodeError):\n        print(\"⚠️  Não consegui ler o arquivo informado.\", file=sys.stderr)\n        return 1\n\n    return executa_codigo(codigo_pt, mostrar_python=mostrar_python)\n\n\nif __name__ == \"__main__\":\n    if len(sys.argv) < 2:\n        print(\n            \"Uso: python -m transpilador_pt.executor arquivo.ptpy [--mostrar-python]\",\n            file=sys.stderr,\n        )\n        sys.exit(1)\n    sys.exit(executa_arquivo(sys.argv[1], mostrar_python=\"--mostrar-python\" in sys.argv))\n"
};
window.TRANSPILADOR_PT_EXEMPLOS = {
  "condicionais": "# Exemplo demonstrativo de condicionais e operadores da Fase 2\n\nfuncao classificar_nota(nota):\n    se nota eh nulo:\n        retorne \"Nota ausente\"\n    senao se nota eh 10:\n        retorne \"Excelente (gabaritou!)\"\n    senao se nota >= 7:\n        retorne \"Aprovado\"\n    senao:\n        retorne \"Em recuperacao\"\n\nnotas = [10, 8.5, 4.0, nulo]\npara valor em notas:\n    mostre(f\"Nota: {valor} -> {classificar_nota(valor)}\")\n\n# Testando operadores compostos de pertinência e negação\nbloqueados = [\"Bruno\", \"Carlos\"]\nusuario = \"Ana\"\n\nse usuario nao em bloqueados:\n    mostre(f\"Acesso liberado para: {usuario}\")\n\nse usuario nao eh \"Bruno\":\n    mostre(\"Confirmado: usuario nao eh o Bruno\")\n",
  "erro": "lista_nums = [10, 20, 30]\nmostre(lista_nums[10])\n",
  "erro_sintaxe": "# Exemplo de diagnóstico didático de erro com apontador visual\n# Tente executar e veja como o erro aponta exatamente onde está o problema!\n\nx = 10\nse x > 5\n    mostre(\"x eh maior que cinco\")\n",
  "funcoes": "# Exemplo de funções matemáticas e builtins curados\nfuncao potencia(base, expoente=2):\n    retorne base ** expoente\n\nvalores = [1, 2, 3, 4, 5]\nquadrados = []\n\npara n em valores:\n    quadrados.append(potencia(n))\n\nmostre(f\"Original: {valores}\")\nmostre(f\"Quadrados: {quadrados}\")\nmostre(f\"Soma total: {some(quadrados)}\")\nmostre(f\"Maior valor: {maximo(quadrados)}\")\nmostre(f\"Menor valor: {minimo(quadrados)}\")\n",
  "loop": "# Exemplo de laço 'para', listas e dicionários\nfrutas = [\"Maca\", \"Banana\", \"Laranja\", \"Uva\"]\n\nmostre(\"--- Lista de Frutas ---\")\npara item em frutas:\n    mostre(f\"- Fruta: {item} (letras: {tamanho(item)})\")\n\nprecos = {\n    \"Maca\": 3.50,\n    \"Banana\": 2.20,\n    \"Laranja\": 4.00,\n}\n\nmostre(\"\")\nmostre(f\"Preco da Maca: R$ {precos['Maca']:.2f}\")\n",
  "ola": "funcao saudacao(nome):\n    se nome eh nulo:\n        retorne \"sem nome\"\n    senao:\n        retorne \"Ola, \" + nome\n\nnomes = [\"Ana\", \"Bruno\", \"Carla\"]\npara nome em nomes:\n    mostre(saudacao(nome))\n\nmostre(f\"Total de nomes: {tamanho(nomes)}\")\n"
};
